document.addEventListener('DOMContentLoaded',()=>{const announcementBar=document.getElementById('announcementBar');const closeAnnouncement=document.getElementById('closeAnnouncement');if(closeAnnouncement && announcementBar){closeAnnouncement.addEventListener('click',()=>{announcementBar.classList.add('hidden');});}const navbar=document.getElementById('navbar');const handleNavScroll=()=>{navbar.classList.toggle('scrolled',window.scrollY>40);};window.addEventListener('scroll',handleNavScroll,{passive:true});const navToggle=document.getElementById('navToggle');const navLinks=document.getElementById('navLinks');if(navToggle && navLinks){const closeMenu=()=>{navToggle.classList.remove('active');navLinks.classList.remove('active');navToggle.setAttribute('aria-expanded','false');document.body.style.overflow='';};navToggle.addEventListener('click',()=>{const isActive=navLinks.classList.toggle('active');navToggle.classList.toggle('active',isActive);navToggle.setAttribute('aria-expanded',String(isActive));document.body.style.overflow=isActive ? 'hidden':'';});navLinks.querySelectorAll('a').forEach(link=>{link.addEventListener('click',closeMenu);});document.addEventListener('keydown',(e)=>{if(e.key==='Escape' && navLinks.classList.contains('active')){closeMenu();navToggle.focus();}});}const faqItems=document.querySelectorAll('.faq-item');faqItems.forEach(item=>{const question=item.querySelector('.faq-question');const answer=item.querySelector('.faq-answer');question.addEventListener('click',()=>{const isActive=item.classList.contains('active');faqItems.forEach(other=>{if(other.classList.contains('active')){const otherAnswer=other.querySelector('.faq-answer');otherAnswer.style.maxHeight=otherAnswer.scrollHeight+'px';void otherAnswer.offsetHeight;otherAnswer.style.maxHeight='0';other.classList.remove('active');}});if(!isActive){item.classList.add('active');answer.style.maxHeight=answer.scrollHeight+'px';}});});const observerOptions={threshold:0.1,rootMargin:['0px','0px','-30px','0px'].join(' ')};const animateOnScroll=new IntersectionObserver((entries)=>{entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('visible');animateOnScroll.unobserve(entry.target);}});},observerOptions);document.querySelectorAll('.fade-in,.fade-in-left,.fade-in-right').forEach(el=>{animateOnScroll.observe(el);});const counterObserver=new IntersectionObserver((entries)=>{entries.forEach(entry=>{if(entry.isIntersecting){const el=entry.target;const target=parseInt(el.dataset.target);if(isNaN(target))return;animateCounter(el,target);counterObserver.unobserve(el);}});},{threshold:0.3});document.querySelectorAll('[data-target]').forEach(el=>{counterObserver.observe(el);});function animateCounter(element,target){const duration=1600;const startTime=performance.now();const suffix=element.dataset.suffix || '';function easeOutExpo(t){return t===1 ? 1:1-Math.pow(2,-10*t);}function update(currentTime){const elapsed=currentTime-startTime;const progress=Math.min(elapsed/duration,1);const easedProgress=easeOutExpo(progress);const current=Math.round(easedProgress*target);element.textContent=current.toLocaleString()+suffix;if(progress<1){requestAnimationFrame(update);}}requestAnimationFrame(update);}let barsAnimated=false;function animateBars(){if(barsAnimated)return;barsAnimated=true;document.querySelectorAll('.bar-fill').forEach((bar,index)=>{const width=bar.dataset.width;setTimeout(()=>{bar.style.width=width;},index*120);});}const dashboard=document.querySelector('.hero-dashboard');if(dashboard){const dashboardObserver=new IntersectionObserver((entries)=>{entries.forEach(entry=>{if(entry.isIntersecting){const heroVisual=document.querySelector('.hero-visual');if(!heroVisual || window.getComputedStyle(heroVisual).display!=='none'){setTimeout(animateBars,600);}dashboardObserver.unobserve(entry.target);}});},{threshold:0.2});dashboardObserver.observe(dashboard);}document.querySelectorAll('a[href^="#"]').forEach(anchor=>{anchor.addEventListener('click',(e)=>{const targetId=anchor.getAttribute('href');if(targetId==='#')return;const targetEl=document.querySelector(targetId);if(targetEl){e.preventDefault();const navHeight=navbar ? navbar.offsetHeight:0;const targetPosition=targetEl.getBoundingClientRect().top+window.scrollY-navHeight-16;window.scrollTo({top:targetPosition,behavior:'smooth'});}});});const sections=document.querySelectorAll('section[id]');function highlightNav(){const scrollPos=window.scrollY+(navbar ? navbar.offsetHeight:0)+80;sections.forEach(section=>{const top=section.offsetTop;const bottom=top+section.offsetHeight;const id=section.getAttribute('id');const link=navLinks ? navLinks.querySelector(`a[href="#${id}"]`):null;if(link &&!link.classList.contains('nav-cta')){if(scrollPos>=top && scrollPos<bottom){link.classList.add('nav-active');}else{link.classList.remove('nav-active');}}});}window.addEventListener('scroll',highlightNav,{passive:true});const cards=document.querySelectorAll('.module-card');cards.forEach(card=>{card.addEventListener('mousemove',e=>{const rect=card.getBoundingClientRect();const x=e.clientX-rect.left;const y=e.clientY-rect.top;card.style.setProperty('--mouse-x',`${x}px`);card.style.setProperty('--mouse-y',`${y}px`);});});const ctaSelectors=['.btn-primary[href*="/book"]','.nav-cta[href*="/book"]','.btn-ghost[href*="/book"]','#finalCta'];document.querySelectorAll(ctaSelectors.join(',')).forEach(el=>{el.addEventListener('click',()=>{if(typeof gtag==='function'){gtag('event','cta_click',{event_category:'engagement',event_label:el.textContent.trim(),link_url:el.getAttribute('href')});}});});});